/*
 * Emergency Fund Vault
 * 20 seconds | one scene | seamless loop | pure Canvas 2D
 * Master: 3840 x 2160, 60 fps. Also scales to FHD and 2K.
 * Background: solid #00FF00. No green foreground, glow, blur or external assets.
 * Configure the VIDEO ENCODER for 100 Mbps CBR. Canvas JS does not encode video.
 * Public interface: draw(ctx, time, width, height); time is in SECONDS.
 */
const FinanceEmergencyFundVault = (() => {
  const TAU = Math.PI * 2;
  const P = Object.freeze({
    key: '#00FF00', ink: '#233550', navy: '#314768',
    blue: '#5078DF', blueDark: '#3659B3', blueLight: '#BBCFFA',
    bluePale: '#EAF0FF', white: '#FFFFFF', cream: '#FFF8E9',
    gold: '#F3BD58', goldDark: '#C98C36', goldLight: '#FFE3A2',
    coral: '#E98175', coralLight: '#F9D8CE',
    violet: '#9785CB', violetLight: '#E6DFF5',
    gray: '#8C9AB0', line: '#D8E0EE'
  });
  const wrap = value => ((value % 1) + 1) % 1;
  const focus = (index, u) => Math.pow(0.5 + 0.5 * Math.cos(TAU * (u - index / 4)), 8);

  function mix(a, b, amount) {
    const av = parseInt(a.slice(1), 16), bv = parseInt(b.slice(1), 16);
    const channel = shift => Math.round(((av >> shift) & 255) * (1 - amount) + ((bv >> shift) & 255) * amount);
    return 'rgb(' + channel(16) + ',' + channel(8) + ',' + channel(0) + ')';
  }

  function rr(ctx, x, y, w, h, r, fill, stroke = P.ink, weight = 3.5) {
    r = Math.max(0, Math.min(r, w / 2, h / 2));
    ctx.beginPath();
    ctx.moveTo(x + r, y);
    ctx.lineTo(x + w - r, y);
    ctx.quadraticCurveTo(x + w, y, x + w, y + r);
    ctx.lineTo(x + w, y + h - r);
    ctx.quadraticCurveTo(x + w, y + h, x + w - r, y + h);
    ctx.lineTo(x + r, y + h);
    ctx.quadraticCurveTo(x, y + h, x, y + h - r);
    ctx.lineTo(x, y + r);
    ctx.quadraticCurveTo(x, y, x + r, y);
    ctx.closePath();
    if (fill) { ctx.fillStyle = fill; ctx.fill(); }
    if (stroke && weight > 0) { ctx.strokeStyle = stroke; ctx.lineWidth = weight; ctx.stroke(); }
  }

  function circle(ctx, x, y, r, fill, stroke = P.ink, weight = 3.5) {
    ctx.beginPath();
    ctx.arc(x, y, r, 0, TAU);
    if (fill) { ctx.fillStyle = fill; ctx.fill(); }
    if (stroke && weight > 0) { ctx.strokeStyle = stroke; ctx.lineWidth = weight; ctx.stroke(); }
  }

  function ellipse(ctx, x, y, rx, ry, fill, stroke = P.ink, weight = 3) {
    ctx.beginPath(); ctx.ellipse(x, y, rx, ry, 0, 0, TAU);
    if (fill) { ctx.fillStyle = fill; ctx.fill(); }
    if (stroke && weight > 0) { ctx.strokeStyle = stroke; ctx.lineWidth = weight; ctx.stroke(); }
  }

  function line(ctx, points, color = P.ink, weight = 3.5) {
    ctx.beginPath(); ctx.moveTo(points[0][0], points[0][1]);
    for (let i = 1; i < points.length; i++) ctx.lineTo(points[i][0], points[i][1]);
    ctx.strokeStyle = color; ctx.lineWidth = weight; ctx.stroke();
  }

  function text(ctx, str, x, y, size, color = P.ink, align = 'left', maxWidth = Infinity, weight = 700) {
    ctx.save();
    ctx.textAlign = align; ctx.textBaseline = 'middle';
    ctx.font = weight + ' ' + size + 'px Arial, Helvetica, sans-serif';
    const measured = ctx.measureText(str).width;
    if (measured > maxWidth) {
      size *= maxWidth / measured;
      ctx.font = weight + ' ' + size + 'px Arial, Helvetica, sans-serif';
    }
    ctx.fillStyle = color; ctx.fillText(str, x, y); ctx.restore();
  }

  function pill(ctx, label, x, y, w, h, fill = P.bluePale, color = P.ink, size = 13) {
    rr(ctx, x, y, w, h, h / 2, fill, null);
    text(ctx, label, x + w / 2, y + h / 2 + 0.5, size, color, 'center', w - 18);
  }

  function coin(ctx, x, y, r) {
    ctx.save(); ctx.translate(x, y);
    circle(ctx, 0, 0, r, P.gold, P.ink, Math.max(2, r * 0.075));
    circle(ctx, 0, 0, r * 0.76, null, P.goldDark, Math.max(1.6, r * 0.06));
    ctx.beginPath(); ctx.arc(0, 0, r * 0.86, -2.6, -1.55);
    ctx.strokeStyle = P.goldLight; ctx.lineWidth = Math.max(2, r * 0.09); ctx.stroke();
    const w = r * 0.28, h = r * 0.37;
    ctx.beginPath();
    ctx.moveTo(w, -h * 0.7);
    ctx.bezierCurveTo(-w * 0.8, -h * 1.5, -w * 1.65, -h * 0.1, 0, 0);
    ctx.bezierCurveTo(w * 1.65, h * 0.1, w * 0.8, h * 1.5, -w, h * 0.7);
    ctx.strokeStyle = P.ink; ctx.lineWidth = Math.max(2, r * 0.09); ctx.stroke();
    line(ctx, [[0, -h * 1.25], [0, h * 1.25]], P.ink, Math.max(2, r * 0.075));
    ctx.restore();
  }

  function stack(ctx, x, baseline, radius, count) {
    const top = baseline - (count - 1) * 13;
    ctx.beginPath(); ctx.moveTo(x - radius, top);
    ctx.lineTo(x - radius, baseline);
    ctx.ellipse(x, baseline, radius, 11, 0, Math.PI, 0, true);
    ctx.lineTo(x + radius, top); ctx.closePath();
    ctx.fillStyle = P.gold; ctx.fill(); ctx.strokeStyle = P.ink; ctx.lineWidth = 3; ctx.stroke();
    for (let i = 1; i < count - 1; i++) {
      ctx.beginPath(); ctx.ellipse(x, top + i * 13, radius, 11, 0, 0, Math.PI);
      ctx.strokeStyle = P.goldDark; ctx.lineWidth = 3; ctx.stroke();
    }
    ellipse(ctx, x, top, radius, 11, P.gold, P.ink, 3);
    ellipse(ctx, x, top, radius * 0.49, 4.8, null, P.goldDark, 2);
  }

  function arrow(ctx, x, y, angle, color = P.ink, size = 7, weight = 3) {
    ctx.save(); ctx.translate(x, y); ctx.rotate(angle);
    line(ctx, [[-size, -size], [0, 0], [-size, size]], color, weight);
    ctx.restore();
  }

  function polyPoint(points, p) {
    const lengths = []; let total = 0;
    for (let i = 1; i < points.length; i++) {
      total += Math.hypot(points[i][0] - points[i-1][0], points[i][1] - points[i-1][1]);
      lengths.push(total);
    }
    const distance = Math.max(0, Math.min(1, p)) * total;
    let prior = 0;
    for (let i = 0; i < lengths.length; i++) {
      if (distance <= lengths[i] || i === lengths.length - 1) {
        const f = (distance - prior) / (lengths[i] - prior || 1);
        return [points[i][0] + (points[i+1][0] - points[i][0]) * f,
          points[i][1] + (points[i+1][1] - points[i][1]) * f];
      }
      prior = lengths[i];
    }
    return points[0];
  }

  function makeCurve(points) {
    const segments = [], samples = [points[0]];
    for (let i = 0; i < points.length - 1; i++) {
      const a = points[i], b = points[i + 1];
      const previous = points[Math.max(0, i - 1)];
      const next = points[Math.min(points.length - 1, i + 2)];
      const c = [a[0] + (b[0] - previous[0]) / 6, a[1] + (b[1] - previous[1]) / 6];
      const d = [b[0] - (next[0] - a[0]) / 6, b[1] - (next[1] - a[1]) / 6];
      segments.push([c, d, b]);
      for (let j = 1; j <= 18; j++) {
        const p = j / 18, q = 1 - p;
        samples.push([q*q*q*a[0] + 3*q*q*p*c[0] + 3*q*p*p*d[0] + p*p*p*b[0],
          q*q*q*a[1] + 3*q*q*p*c[1] + 3*q*p*p*d[1] + p*p*p*b[1]]);
      }
    }
    return { points, segments, samples };
  }

  function strokeCurve(ctx, curve, color, weight) {
    ctx.beginPath(); ctx.moveTo(curve.points[0][0], curve.points[0][1]);
    for (const segment of curve.segments) {
      ctx.bezierCurveTo(segment[0][0], segment[0][1], segment[1][0], segment[1][1], segment[2][0], segment[2][1]);
    }
    ctx.strokeStyle = color; ctx.lineWidth = weight; ctx.stroke();
  }

  function roundedTrack(x, y, w, h, r, progress) {
    const horizontal = w - 2 * r, vertical = h - 2 * r, arc = Math.PI * r / 2;
    const sizes = [horizontal, arc, vertical, arc, horizontal, arc, vertical, arc];
    let d = wrap(progress) * sizes.reduce((a, b) => a + b, 0);
    let i = 0;
    while (i < 7 && d > sizes[i]) { d -= sizes[i]; i++; }
    if (i === 0) return [x + r + d, y, 0];
    if (i === 2) return [x + w, y + r + d, Math.PI / 2];
    if (i === 4) return [x + w - r - d, y + h, Math.PI];
    if (i === 6) return [x, y + h - r - d, -Math.PI / 2];
    const starts = [-Math.PI / 2, 0, Math.PI / 2, Math.PI];
    const corner = (i - 1) / 2;
    const cx = corner < 2 ? x + w - r : x + r;
    const cy = (corner === 0 || corner === 3) ? y + r : y + h - r;
    const angle = starts[corner] + d / r;
    return [cx + r * Math.cos(angle), cy + r * Math.sin(angle), angle + Math.PI / 2];
  }

  function icon(ctx, type, x, y, size, color = P.blue) {
    ctx.save(); ctx.translate(x, y); ctx.scale(size / 48, size / 48);
    if (type === 0) {
      rr(ctx, -18, 3, 9, 15, 2, color, null);
      rr(ctx, -4, -5, 9, 23, 2, color, null);
      rr(ctx, 10, -15, 9, 33, 2, color, null);
      line(ctx, [[-18, -8], [-3, -18], [13, -22]], P.ink, 2.5);
      arrow(ctx, 13, -22, -0.25, P.ink, 5, 2.5);
    } else if (type === 1) {
      rr(ctx, -15, -20, 29, 39, 4, P.cream, P.ink, 2.5);
      line(ctx, [[-8, -11], [7, -11]], color, 3);
      line(ctx, [[-8, -3], [4, -3]], color, 3);
      circle(ctx, 7, 10, 7, color, P.ink, 2);
    } else if (type === 2) {
      rr(ctx, -18, -12, 27, 30, 4, P.violetLight, P.ink, 2.5);
      rr(ctx, -5, -20, 26, 30, 4, P.white, P.ink, 2.5);
      line(ctx, [[1, -12], [15, -12]], color, 3);
      line(ctx, [[1, -4], [11, -4]], color, 3);
    } else {
      rr(ctx, -21, -14, 41, 30, 5, color, P.ink, 2.5);
      rr(ctx, 3, -6, 21, 14, 3, P.cream, P.ink, 2.2);
      circle(ctx, 10, 1, 2.1, P.ink, null);
      line(ctx, [[-12, -7], [-3, -7]], P.white, 2.5);
    }
    ctx.restore();
  }

  // Fixed rounded routes, sampled once for uniform travel speed.
  function makeRoute(points, radius = 28) {
    const commands = [], samples = [points[0]];
    const appendLine = p => { commands.push(['L', p]); samples.push(p); };
    for (let i = 1; i < points.length - 1; i++) {
      const p = points[i - 1], c = points[i], n = points[i + 1];
      const before = Math.hypot(c[0] - p[0], c[1] - p[1]);
      const after = Math.hypot(n[0] - c[0], n[1] - c[1]);
      const r = Math.min(radius, before / 2, after / 2);
      const a = [c[0] - (c[0] - p[0]) / before * r, c[1] - (c[1] - p[1]) / before * r];
      const b = [c[0] + (n[0] - c[0]) / after * r, c[1] + (n[1] - c[1]) / after * r];
      appendLine(a); commands.push(['Q', c, b]);
      for (let k = 1; k <= 20; k++) {
        const v = k / 20, q = 1 - v;
        samples.push([q * q * a[0] + 2 * q * v * c[0] + v * v * b[0],
          q * q * a[1] + 2 * q * v * c[1] + v * v * b[1]]);
      }
    }
    appendLine(points[points.length - 1]);
    const distances = [0];
    for (let i = 1; i < samples.length; i++) {
      distances.push(distances[i - 1] + Math.hypot(samples[i][0] - samples[i - 1][0], samples[i][1] - samples[i - 1][1]));
    }
    return { commands, samples, distances, length: distances[distances.length - 1] };
  }

  function routeStroke(ctx, route, color, weight) {
    ctx.beginPath(); ctx.moveTo(...route.samples[0]);
    for (const c of route.commands) {
      if (c[0] === 'L') ctx.lineTo(...c[1]);
      else ctx.quadraticCurveTo(...c[1], ...c[2]);
    }
    ctx.strokeStyle = color; ctx.lineWidth = weight; ctx.stroke();
  }

  function routePoint(route, progress) {
    const d = Math.max(0, Math.min(1, progress)) * route.length;
    let lo = 1, hi = route.distances.length - 1;
    while (lo < hi) {
      const mid = (lo + hi) >> 1;
      if (route.distances[mid] < d) lo = mid + 1;
      else hi = mid;
    }
    const a = route.samples[lo - 1], b = route.samples[lo];
    const span = route.distances[lo] - route.distances[lo - 1];
    const f = span > 0 ? (d - route.distances[lo - 1]) / span : 0;
    return [a[0] + (b[0] - a[0]) * f, a[1] + (b[1] - a[1]) * f];
  }

  const depositRoute = makeRoute([[538, 312], [650, 312], [650, 263], [992, 263], [992, 370]], 25);
  const reserveCategories = [
    { y: 184, title: 'HOME COVER', sub: 'ESSENTIAL COSTS', value: '3 MONTHS', kind: 0, ratio: 0.76, color: P.blue },
    { y: 420, title: 'HEALTH COVER', sub: 'MEDICAL RESERVE', value: '6 MONTHS', kind: 1, ratio: 0.88, color: P.coral },
    { y: 656, title: 'INCOME COVER', sub: 'CAREER BUFFER', value: '3 MONTHS', kind: 2, ratio: 0.70, color: P.violet }
  ];

  function reserveSymbol(ctx, type, x, y, size, color) {
    ctx.save(); ctx.translate(x, y); ctx.scale(size / 56, size / 56);
    if (type === 0) {
      ctx.beginPath(); ctx.moveTo(-23, -1); ctx.lineTo(0, -21); ctx.lineTo(23, -1);
      ctx.lineTo(18, -1); ctx.lineTo(18, 21); ctx.lineTo(-18, 21); ctx.lineTo(-18, -1);
      ctx.closePath(); ctx.fillStyle = color; ctx.fill(); ctx.strokeStyle = P.ink; ctx.lineWidth = 2.6; ctx.stroke();
      rr(ctx, -5, 6, 10, 15, 1.5, P.cream, P.ink, 2.2);
      rr(ctx, -11, -4, 7, 7, 1, P.white, null);
      rr(ctx, 4, -4, 7, 7, 1, P.white, null);
    } else if (type === 1) {
      rr(ctx, -20, -20, 40, 40, 9, P.white, P.ink, 2.5);
      ctx.beginPath(); ctx.moveTo(-6, -13); ctx.lineTo(6, -13); ctx.lineTo(6, -6);
      ctx.lineTo(13, -6); ctx.lineTo(13, 6); ctx.lineTo(6, 6); ctx.lineTo(6, 13);
      ctx.lineTo(-6, 13); ctx.lineTo(-6, 6); ctx.lineTo(-13, 6); ctx.lineTo(-13, -6);
      ctx.lineTo(-6, -6); ctx.closePath(); ctx.fillStyle = color; ctx.fill();
    } else {
      rr(ctx, -9, -21, 18, 10, 3, null, P.ink, 2.7);
      rr(ctx, -23, -12, 46, 32, 5, color, P.ink, 2.7);
      line(ctx, [[-23, 0], [23, 0]], P.ink, 2.5);
      rr(ctx, -5, -4, 10, 10, 2, P.cream, P.ink, 2);
    }
    ctx.restore();
  }

  function balanceCard(ctx, u) {
    rr(ctx, 140, 177, 430, 286, 24, P.white, P.ink, 3.8);
    ctx.save(); rr(ctx, 142, 179, 426, 282, 22, null, null); ctx.clip();
    rr(ctx, 140, 177, 430, 70, 0, P.navy, null); ctx.restore();
    text(ctx, 'RESERVE BALANCE', 177, 213, 22, P.white, 'left', 265);
    circle(ctx, 529, 212, 12, P.gold, null);
    line(ctx, [[524, 212], [528, 216], [535, 208]], P.ink, 2.5);
    text(ctx, '$24,800', 177, 303, 54, P.ink, 'left', 352);
    text(ctx, '$30,000 TARGET', 179, 350, 15, P.navy, 'left', 258);
    const amount = 0.806 + 0.012 * Math.sin(TAU * u);
    rr(ctx, 178, 378, 354, 15, 7.5, P.bluePale, null);
    rr(ctx, 178, 378, 354 * amount, 15, 7.5, P.blue, null);
    text(ctx, 'CASH READY', 178, 426, 13, P.navy, 'left', 180);
    pill(ctx, 'PROTECTED', 410, 410, 123, 29, P.goldLight, P.ink, 11);
  }

  function envelope(ctx, x, y, color, label, detail) {
    rr(ctx, x, y, 156, 95, 10, P.white, P.ink, 3.2);
    ctx.save(); rr(ctx, x + 1.6, y + 1.6, 152.8, 91.8, 8, null, null); ctx.clip();
    ctx.beginPath(); ctx.moveTo(x, y + 4); ctx.lineTo(x + 78, y + 56); ctx.lineTo(x + 156, y + 4);
    ctx.closePath(); ctx.fillStyle = color; ctx.fill(); ctx.strokeStyle = P.ink; ctx.lineWidth = 3; ctx.stroke();
    ctx.restore();
    line(ctx, [[x + 8, y + 86], [x + 48, y + 54]], P.line, 2.4);
    line(ctx, [[x + 148, y + 86], [x + 108, y + 54]], P.line, 2.4);
    circle(ctx, x + 78, y + 43, 10, P.gold, P.ink, 2.2);
    text(ctx, label, x + 78, y + 126, 14, P.ink, 'center', 156);
    text(ctx, detail, x + 78, y + 151, 12, P.navy, 'center', 156, 500);
  }

  function reserveEnvelopes(ctx) {
    rr(ctx, 140, 546, 430, 267, 24, P.cream, P.ink, 3.6);
    text(ctx, 'RESERVE BUCKETS', 178, 581, 19, P.ink, 'left', 347);
    line(ctx, [[178, 604], [532, 604]], P.line, 2.5);
    envelope(ctx, 178, 629, P.blueLight, 'ESSENTIALS', 'DAILY SECURITY');
    envelope(ctx, 376, 629, P.coralLight, 'BUFFER', 'EXTRA CAPACITY');
  }

  function coverageCard(ctx, data, index, u) {
    const active = focus(index, u);
    const y = data.y;
    rr(ctx, 1374, y, 410, 176, 22, P.white, mix(P.line, P.ink, 0.34 + 0.26 * active), 3.4);
    circle(ctx, 1433, y + 58, 35, mix(P.bluePale, P.goldLight, active * 0.65), null);
    reserveSymbol(ctx, data.kind, 1433, y + 58, 49, data.color);
    text(ctx, data.title, 1489, y + 40, 23, P.ink, 'left', 260);
    text(ctx, data.sub, 1490, y + 77, 12, P.navy, 'left', 251, 500);
    rr(ctx, 1402, y + 114, 354, 11, 5.5, P.bluePale, null);
    const ratio = data.ratio + 0.012 * Math.sin(TAU * u + index * 1.1);
    rr(ctx, 1402, y + 114, 354 * ratio, 11, 5.5, mix(data.color, P.gold, active * 0.65), null);
    text(ctx, data.value, 1403, y + 148, 13, P.navy, 'left', 220);
    circle(ctx, 1738, y + 149, 9, mix(P.blueLight, P.gold, active), null);
    line(ctx, [[1734, y + 149], [1737, y + 152], [1743, y + 145]], P.ink, 2);
  }

  function vaultBody(ctx, loopT, u) {
    // Stable feet, casing, door and hinges; only the internal dial turns.
    rr(ctx, 758, 848, 86, 61, 9, P.navy, P.ink, 3.5);
    rr(ctx, 1131, 848, 86, 61, 9, P.navy, P.ink, 3.5);
    rr(ctx, 663, 911, 652, 24, 12, P.cream, P.ink, 3.5);
    rr(ctx, 710, 333, 560, 526, 30, P.blueDark, P.ink, 4.6);
    rr(ctx, 710, 333, 535, 503, 29, P.blue, P.ink, 4);
    rr(ctx, 735, 397, 485, 411, 24, P.blueLight, P.ink, 3.8);
    rr(ctx, 751, 351, 196, 31, 9, P.cream, P.ink, 2.6);
    text(ctx, 'EMERGENCY FUND', 849, 367, 14, P.ink, 'center', 176);
    pill(ctx, 'SECURE', 1080, 351, 139, 31, mix(P.cream, P.goldLight, focus(3, u)), P.ink, 12);
    circle(ctx, 992, 600, 177, P.navy, P.ink, 4);
    circle(ctx, 992, 600, 162, P.cream, P.ink, 3.4);
    circle(ctx, 992, 600, 145, null, P.line, 3);
    for (const y of [478, 691]) {
      rr(ctx, 776, y, 60, 43, 10, P.navy, P.ink, 3.2);
      rr(ctx, 786, y + 8, 12, 27, 4, P.blueLight, null);
      line(ctx, [[816, y + 6], [816, y + 37]], P.blueLight, 3);
    }
    circle(ctx, 976, 587, 66, P.blueLight, P.ink, 3.4);
    circle(ctx, 976, 587, 53, P.white, P.ink, 2.5);
    for (let i = 0; i < 20; i++) {
      const angle = TAU * i / 20;
      const a = i % 5 === 0 ? 43 : 46;
      line(ctx, [[976 + Math.cos(angle) * a, 587 + Math.sin(angle) * a],
        [976 + Math.cos(angle) * 49, 587 + Math.sin(angle) * 49]], P.navy, i % 5 === 0 ? 3 : 2);
    }
    ctx.save(); ctx.translate(976, 587);
    ctx.rotate(-0.3 + 0.15 * Math.sin(TAU * loopT / 10));
    circle(ctx, 0, 0, 33, P.gold, P.ink, 2.8);
    line(ctx, [[0, -23], [0, -12]], P.ink, 3.8);
    circle(ctx, 0, 0, 12, P.goldLight, P.ink, 2.3);
    ctx.restore();
    // A fixed handle attached to the same door plane.
    rr(ctx, 1098, 548, 26, 86, 10, P.navy, P.ink, 2.5);
    rr(ctx, 1115, 557, 26, 67, 10, P.white, P.ink, 3);
    circle(ctx, 1111, 559, 3, P.blueLight, null);
    circle(ctx, 1111, 623, 3, P.blueLight, null);
    pill(ctx, 'CASH RESERVE', 914, 692, 160, 29, P.bluePale, P.navy, 11);
    text(ctx, '$24,800 RESERVED', 989, 826, 14, P.white, 'center', 420);
    // Opaque intake lip masks the depositing coin at the receiving endpoint.
    rr(ctx, 956, 319, 72, 22, 8, P.navy, P.ink, 3.2);
    rr(ctx, 966, 323, 52, 6, 3, P.ink, null);
    line(ctx, [[962, 337], [1022, 337]], P.blueLight, 2);
  }

  function render(ctx, loopT, sceneProgress) {
    const u = sceneProgress;
    ctx.lineCap = 'round'; ctx.lineJoin = 'round';
    pill(ctx, 'EMERGENCY FUND', 818, 157, 347, 46, P.cream, P.ink, 20);
    // Both reset positions are fully inside opaque source/receiver geometry.
    routeStroke(ctx, depositRoute, P.goldDark, 6);
    routeStroke(ctx, depositRoute, P.goldLight, 2.3);
    const p = wrap(loopT / 5);
    const deposit = routePoint(depositRoute, p);
    coin(ctx, deposit[0], deposit[1], 14);
    balanceCard(ctx, u);
    reserveEnvelopes(ctx);
