    const horizontal = w - 2 * r, vertical = h - 2 * r, arc = Math.PI * r / 2;
    const sizes = [horizontal, arc, vertical, arc, horizontal, arc, vertical, arc];
    let d = wrap(progress) * sizes.reduce((a, b) => a + b, 0);
    let i = 0;
    while (i < 7 && d > sizes[i]) { d -= sizes[i]; i++; }
    if (i === 0) return [x + r + d, y, 0];
    if (i === 2) return [x + w, y + r + d, Math.PI / 2];
    if (i === 4) return [x + w - r - d, y + h, Math.PI];
    if (i === 6) return [x, y + h - r - d, -Math.PI / 2];
