      const next = points[Math.min(points.length - 1, i + 2)];
      const c = [a[0] + (b[0] - previous[0]) / 6, a[1] + (b[1] - previous[1]) / 6];
      const d = [b[0] - (next[0] - a[0]) / 6, b[1] - (next[1] - a[1]) / 6];
