    rr(ctx, 543, 211, 834, 547, 15, P.bluePale, P.ink, 3);
    rr(ctx, 564, 231, 792, 65, 13, P.white, null);
    text(ctx, 'PORTFOLIO', 589, 264, 25, P.ink, 'left', 410);
    pill(ctx, 'OVERVIEW', 1202, 250, 129, 29, P.bluePale, P.blueDark, 12);
    rr(ctx, 566, 314, 366, 398, 17, P.white, P.line, 2);
    rr(ctx, 951, 314, 403, 204, 17, P.white, P.line, 2);
    rr(ctx, 951, 534, 403, 178, 17, P.white, P.line, 2);
    donut(ctx, values, u);

    text(ctx, 'VALUE TREND', 976, 341, 13, P.ink, 'left', 220);
    for (let i = 0; i < 3; i++) line(ctx, [[980, 378 + i * 48], [1328, 378 + i * 48]], P.line, 1.5);
    strokeCurve(ctx, trend, P.blue, 4);
    const marker = polyPoint(trend.samples, 0.5 - 0.5 * Math.cos(phase));
