    line(ctx, [[568, 725], [1352, 725]], P.line, 2);
    text(ctx, 'DIVERSIFIED PORTFOLIO', 589, 741, 10, P.gray, 'left', 256, 600);
    circle(ctx, 944, 778, 3.5, P.blueLight, null);
    circle(ctx, 960, 778, 3.5, P.gold, null);
    circle(ctx, 976, 778, 3.5, P.blueLight, null);
