    calculator(ctx);
    stack(ctx, 1511, 919, 42, 4);
    stack(ctx, 1626, 919, 42, 7);
    stack(ctx, 1741, 919, 42, 10);
    coin(ctx, 1420, 889, 30);
  }

  return Object.freeze({ render });
})();

function draw(ctx, time, width, height) {
  const t = time;
  const duration = 20;
  const sceneCount = 1;
  const loopT = t % duration;
  const sceneDuration = duration / sceneCount;
  const currentScene = Math.floor(loopT / sceneDuration);
  const sceneProgress = (loopT % sceneDuration) / sceneDuration;
  const minSide = Math.min(width, height);
  if (!(width > 0 && height > 0)) return;
  const unit = Math.min(width / 1920, height / 1080, minSide / 1080);

  ctx.save();
  ctx.setTransform(1, 0, 0, 1, 0, 0);
  ctx.globalAlpha = 1;
  ctx.globalCompositeOperation = 'source-over';
  ctx.shadowBlur = 0;
  ctx.shadowOffsetX = 0;
  ctx.shadowOffsetY = 0;
  ctx.shadowColor = 'transparent';
  if ('filter' in ctx) ctx.filter = 'none';
  ctx.setLineDash([]);
  ctx.lineDashOffset = 0;
  ctx.fillStyle = '#00FF00';
  ctx.fillRect(0, 0, width, height);
  ctx.translate((width - 1920 * unit) / 2, (height - 1080 * unit) / 2);
  ctx.scale(unit, unit);
  if (currentScene === 0) {
    FinancePortfolioDashboard.render(ctx, loopT, sceneProgress);
  }
  ctx.restore();
}

draw.exportSettings = Object.freeze({
  duration: 20,
  sceneCount: 1,
  width: 3840,
  height: 2160,
  frameRate: 60,
  videoBitrate: 100000000,
  minimumVideoBitrate: 100000000,
  maximumVideoBitrate: 100000000,
  rateControl: 'CBR'
});

/*
 * Compound Interest Garden
 * 20 seconds | one scene | seamless loop | pure Canvas 2D
 * Master: 3840 x 2160, 60 fps. Also scales to FHD and 2K.
 * Background: solid #00FF00. No green foreground, glow, blur or external assets.
 * Configure the VIDEO ENCODER for 100 Mbps CBR. Canvas JS does not encode video.
 * Public interface: draw(ctx, time, width, height); time is in SECONDS.
 */
const FinanceInvestmentGarden = (() => {
  const TAU = Math.PI * 2;
  const P = Object.freeze({
    key: '#00FF00', ink: '#233550', navy: '#314768',
    blue: '#5078DF', blueDark: '#3659B3', blueLight: '#BBCFFA',
    bluePale: '#EAF0FF', white: '#FFFFFF', cream: '#FFF8E9',
    gold: '#F3BD58', goldDark: '#C98C36', goldLight: '#FFE3A2',
    coral: '#E98175', coralLight: '#F9D8CE',
    violet: '#9785CB', violetLight: '#E6DFF5',
    gray: '#8C9AB0', line: '#D8E0EE'
