      lengths.push(total);
    }
    const distance = Math.max(0, Math.min(1, p)) * total;
    let prior = 0;
    for (let i = 0; i < lengths.length; i++) {
      if (distance <= lengths[i] || i === lengths.length - 1) {
        const f = (distance - prior) / (lengths[i] - prior || 1);
        return [points[i][0] + (points[i+1][0] - points[i][0]) * f,
          points[i][1] + (points[i+1][1] - points[i][1]) * f];
      }
      prior = lengths[i];
    }
    return points[0];
  }

  function makeCurve(points) {
    const segments = [], samples = [points[0]];
    for (let i = 0; i < points.length - 1; i++) {
      const a = points[i], b = points[i + 1];
      const previous = points[Math.max(0, i - 1)];
      const next = points[Math.min(points.length - 1, i + 2)];
      const c = [a[0] + (b[0] - previous[0]) / 6, a[1] + (b[1] - previous[1]) / 6];
      const d = [b[0] - (next[0] - a[0]) / 6, b[1] - (next[1] - a[1]) / 6];
      segments.push([c, d, b]);
      for (let j = 1; j <= 18; j++) {
        const p = j / 18, q = 1 - p;
        samples.push([q*q*q*a[0] + 3*q*q*p*c[0] + 3*q*p*p*d[0] + p*p*p*b[0],
          q*q*q*a[1] + 3*q*q*p*c[1] + 3*q*p*p*d[1] + p*p*p*b[1]]);
      }
    }
    return { points, segments, samples };
  }

  function strokeCurve(ctx, curve, color, weight) {
    ctx.beginPath(); ctx.moveTo(curve.points[0][0], curve.points[0][1]);
    for (const segment of curve.segments) {
      ctx.bezierCurveTo(segment[0][0], segment[0][1], segment[1][0], segment[1][1], segment[2][0], segment[2][1]);
    }
    ctx.strokeStyle = color; ctx.lineWidth = weight; ctx.stroke();
  }

  function roundedTrack(x, y, w, h, r, progress) {
    const horizontal = w - 2 * r, vertical = h - 2 * r, arc = Math.PI * r / 2;
    const sizes = [horizontal, arc, vertical, arc, horizontal, arc, vertical, arc];
    let d = wrap(progress) * sizes.reduce((a, b) => a + b, 0);
    let i = 0;
    while (i < 7 && d > sizes[i]) { d -= sizes[i]; i++; }
    if (i === 0) return [x + r + d, y, 0];
    if (i === 2) return [x + w, y + r + d, Math.PI / 2];
    if (i === 4) return [x + w - r - d, y + h, Math.PI];
    if (i === 6) return [x, y + h - r - d, -Math.PI / 2];
    const starts = [-Math.PI / 2, 0, Math.PI / 2, Math.PI];
    const corner = (i - 1) / 2;
    const cx = corner < 2 ? x + w - r : x + r;
    const cy = (corner === 0 || corner === 3) ? y + r : y + h - r;
    const angle = starts[corner] + d / r;
    return [cx + r * Math.cos(angle), cy + r * Math.sin(angle), angle + Math.PI / 2];
  }

  function icon(ctx, type, x, y, size, color = P.blue) {
    ctx.save(); ctx.translate(x, y); ctx.scale(size / 48, size / 48);
    if (type === 0) {
      rr(ctx, -18, 3, 9, 15, 2, color, null);
      rr(ctx, -4, -5, 9, 23, 2, color, null);
      rr(ctx, 10, -15, 9, 33, 2, color, null);
      line(ctx, [[-18, -8], [-3, -18], [13, -22]], P.ink, 2.5);
      arrow(ctx, 13, -22, -0.25, P.ink, 5, 2.5);
    } else if (type === 1) {
      rr(ctx, -15, -20, 29, 39, 4, P.cream, P.ink, 2.5);
      line(ctx, [[-8, -11], [7, -11]], color, 3);
      line(ctx, [[-8, -3], [4, -3]], color, 3);
      circle(ctx, 7, 10, 7, color, P.ink, 2);
    } else if (type === 2) {
      rr(ctx, -18, -12, 27, 30, 4, P.violetLight, P.ink, 2.5);
      rr(ctx, -5, -20, 26, 30, 4, P.white, P.ink, 2.5);
      line(ctx, [[1, -12], [15, -12]], color, 3);
      line(ctx, [[1, -4], [11, -4]], color, 3);
    } else {
      rr(ctx, -21, -14, 41, 30, 5, color, P.ink, 2.5);
      rr(ctx, 3, -6, 21, 14, 3, P.cream, P.ink, 2.2);
      circle(ctx, 10, 1, 2.1, P.ink, null);
      line(ctx, [[-12, -7], [-3, -7]], P.white, 2.5);
    }
    ctx.restore();
  }

  const gardenGraph = makeCurve([[195, 542], [246, 530], [294, 534], [346, 493], [394, 503], [448, 456], [520, 414]]);

  function leaf(ctx, x, y, length, breadth, angle, movement, fill) {
    ctx.save(); ctx.translate(x, y); ctx.rotate(angle + movement);
    ctx.beginPath(); ctx.moveTo(0, 0);
    ctx.bezierCurveTo(length * 0.22, -breadth * 0.58, length * 0.68, -breadth * 0.63, length, 0);
    ctx.bezierCurveTo(length * 0.66, breadth * 0.53, length * 0.21, breadth * 0.48, 0, 0);
    ctx.closePath(); ctx.fillStyle = fill; ctx.fill(); ctx.strokeStyle = P.ink; ctx.lineWidth = 4; ctx.stroke();
    ctx.beginPath(); ctx.moveTo(12, 0);
    ctx.quadraticCurveTo(length * 0.48, -breadth * 0.055, length * 0.86, 0);
    ctx.strokeStyle = P.ink; ctx.lineWidth = 2.5; ctx.stroke(); ctx.restore();
  }

  function fruit(ctx, x, y, fromX, fromY, radius, phase, offset) {
    const sway = Math.sin(phase + offset) * 2.5;
    ctx.beginPath(); ctx.moveTo(fromX, fromY);
    ctx.quadraticCurveTo((fromX + x) / 2, fromY - 20, x + sway, y + radius);
    ctx.strokeStyle = P.ink; ctx.lineWidth = 4; ctx.stroke();
    coin(ctx, x + sway, y, radius);
  }

  function growthCard(ctx, u) {
    rr(ctx, 150, 305, 420, 310, 22, P.cream, P.ink, 4);
    rr(ctx, 150, 305, 420, 70, 22, P.white, null);
    line(ctx, [[152, 375], [568, 375]], P.ink, 3);
    text(ctx, 'GROWTH', 183, 341, 24, P.ink, 'left', 220);
    pill(ctx, 'LONG TERM', 423, 326, 118, 29, P.bluePale, P.blueDark, 12);
    for (let i = 0; i < 3; i++) line(ctx, [[190, 425 + i * 56], [530, 425 + i * 56]], P.line, 2);
    line(ctx, [[190, 402], [190, 555], [534, 555]], P.gray, 2);
    strokeCurve(ctx, gardenGraph, P.blue, 5);
    for (const point of gardenGraph.points) circle(ctx, point[0], point[1], 4, P.blue, null);
    const p = polyPoint(gardenGraph.samples, 0.5 - 0.5 * Math.cos(TAU * u));
    circle(ctx, p[0], p[1], 8, P.gold, P.ink, 2.5);
    pill(ctx, 'COMPOUND INTEREST', 184, 572, 213, 25, P.goldLight, P.ink, 11);
    line(ctx, [[442, 584], [524, 584]], P.blue, 3);
    arrow(ctx, 524, 584, 0, P.blue, 6, 3);
    rr(ctx, 150, 305, 420, 310, 22, null, P.ink, 4);
  }

  function reinvestCard(ctx, u) {
    rr(ctx, 1350, 330, 420, 284, 22, P.white, P.ink, 4);
    text(ctx, 'REINVESTMENT', 1382, 367, 22, P.ink, 'left', 320);
    line(ctx, [[1380, 397], [1740, 397]], P.line, 2);
    const labels = ['EARN', 'REINVEST', 'COMPOUND'];
    const colors = [P.gold, P.blue, P.violet];
    for (let i = 0; i < 3; i++) {
      const y = 434 + i * 61;
      const active = Math.pow(0.5 + 0.5 * Math.cos(TAU * (u - i / 3)), 5);
      circle(ctx, 1399, y, 17, mix(P.bluePale, colors[i], active * 0.75), P.ink, 2.5);
      if (i === 0) line(ctx, [[1392, y], [1406, y]], P.ink, 2.5);
      if (i === 1) { line(ctx, [[1390, y + 4], [1405, y - 5]], P.ink, 2.5); arrow(ctx, 1405, y - 5, -0.55, P.ink, 5, 2.5); }
      if (i === 2) { line(ctx, [[1392, y + 5], [1392, y - 2], [1399, y - 2], [1399, y - 8], [1407, y - 8]], P.ink, 2.5); }
      text(ctx, labels[i], 1431, y, 15, P.ink, 'left', 138);
      rr(ctx, 1587, y - 5, 145, 10, 5, P.bluePale, null);
      rr(ctx, 1587, y - 5, 59 + active * 72, 10, 5, colors[i], null);
    }
  }

  function planter(ctx, u) {
    ctx.beginPath(); ctx.moveTo(811, 733);
    ctx.lineTo(1109, 733); ctx.lineTo(1085, 896);
    ctx.quadraticCurveTo(1082, 918, 1059, 918);
    ctx.lineTo(861, 918); ctx.quadraticCurveTo(838, 918, 835, 896);
    ctx.closePath(); ctx.fillStyle = P.blue; ctx.fill(); ctx.strokeStyle = P.ink; ctx.lineWidth = 4.5; ctx.stroke();
    ctx.beginPath(); ctx.moveTo(1068, 742); ctx.lineTo(1106, 742); ctx.lineTo(1083, 896);
    ctx.quadraticCurveTo(1079, 915, 1059, 915); ctx.lineTo(1044, 915); ctx.closePath();
    ctx.fillStyle = P.blueDark; ctx.fill();
    rr(ctx, 790, 704, 340, 44, 13, P.blueLight, P.ink, 4.5);
    line(ctx, [[811, 718], [1109, 718]], P.bluePale, 3);
    rr(ctx, 850, 780, 220, 93, 15, P.cream, P.ink, 3);
    text(ctx, 'REINVEST', 960, 809, 21, P.ink, 'center', 180);
    rr(ctx, 875, 840, 170, 9, 4.5, P.blueLight, null);
    const x = 886 + (0.5 - 0.5 * Math.cos(TAU * u)) * 132;
    rr(ctx, x, 840, 17, 9, 4.5, P.blueDark, null);
  }

  function render(ctx, loopT, sceneProgress) {
    const u = sceneProgress, phase = TAU * u;
    ctx.lineCap = 'round'; ctx.lineJoin = 'round';
    ctx.save(); ctx.setLineDash([7, 14]); ctx.lineDashOffset = -u * 210;
    rr(ctx, 640, 145, 640, 690, 100, null, P.bluePale, 3.5); ctx.restore();
    for (let i = 0; i < 4; i++) {
      const p = roundedTrack(640, 145, 640, 690, 100, i / 4 + 0.125);
      arrow(ctx, p[0], p[1], p[2], P.blueLight, 7, 3);
    }
    for (let i = 0; i < 3; i++) {
      const p = roundedTrack(640, 145, 640, 690, 100, u + i / 3);
      coin(ctx, p[0], p[1], 18);
    }

    ctx.beginPath(); ctx.moveTo(960, 720); ctx.lineTo(960, 260);
    ctx.strokeStyle = P.ink; ctx.lineWidth = 13; ctx.stroke();
    ctx.beginPath(); ctx.moveTo(960, 720); ctx.lineTo(960, 260);
    ctx.strokeStyle = P.blueLight; ctx.lineWidth = 6; ctx.stroke();
    fruit(ctx, 745, 317, 960, 393, 28, phase, 0.2);
    fruit(ctx, 1190, 365, 960, 459, 28, phase, 2.2);
    fruit(ctx, 744, 631, 960, 666, 25, phase, 3.8);
    leaf(ctx, 960, 353, 170, 76, -2.62, Math.sin(phase) * 0.014, P.gold);
    leaf(ctx, 960, 404, 174, 76, -0.55, Math.sin(phase + 0.7) * 0.014, P.blueLight);
    leaf(ctx, 960, 494, 204, 84, -2.72, Math.sin(phase + 1.2) * 0.013, P.blue);
    leaf(ctx, 960, 545, 205, 84, -0.42, Math.sin(phase + 1.8) * 0.013, P.gold);
    leaf(ctx, 960, 629, 186, 76, -2.82, Math.sin(phase + 2.4) * 0.012, P.goldLight);
    leaf(ctx, 960, 675, 174, 72, -0.30, Math.sin(phase + 3) * 0.012, P.blueLight);
    coin(ctx, 960, 219, 38);

    growthCard(ctx, u); reinvestCard(ctx, u);
    stack(ctx, 241, 908, 43, 5);
    stack(ctx, 366, 908, 43, 8);
    stack(ctx, 491, 908, 43, 12);
    stack(ctx, 1429, 908, 43, 12);
    stack(ctx, 1554, 908, 43, 8);
    stack(ctx, 1679, 908, 43, 5);
    coin(ctx, 587, 887, 32);
    coin(ctx, 1333, 887, 32);
    planter(ctx, u);
  }

  return Object.freeze({ render });
})();

function draw(ctx, time, width, height) {
  const t = time;
  const duration = 20;
  const sceneCount = 1;
  const loopT = t % duration;
  const sceneDuration = duration / sceneCount;
  const currentScene = Math.floor(loopT / sceneDuration);
  const sceneProgress = (loopT % sceneDuration) / sceneDuration;
  const minSide = Math.min(width, height);
  if (!(width > 0 && height > 0)) return;
  const unit = Math.min(width / 1920, height / 1080, minSide / 1080);

  ctx.save();
  ctx.setTransform(1, 0, 0, 1, 0, 0);
  ctx.globalAlpha = 1;
  ctx.globalCompositeOperation = 'source-over';
  ctx.shadowBlur = 0;
  ctx.shadowOffsetX = 0;
  ctx.shadowOffsetY = 0;
  ctx.shadowColor = 'transparent';
  if ('filter' in ctx) ctx.filter = 'none';
  ctx.setLineDash([]);
  ctx.lineDashOffset = 0;
  ctx.fillStyle = '#00FF00';
  ctx.fillRect(0, 0, width, height);
  ctx.translate((width - 1920 * unit) / 2, (height - 1080 * unit) / 2);
  ctx.scale(unit, unit);
  if (currentScene === 0) {
    FinanceInvestmentGarden.render(ctx, loopT, sceneProgress);
  }
  ctx.restore();
}

draw.exportSettings = Object.freeze({
  duration: 20,
  sceneCount: 1,
  width: 3840,
  height: 2160,
  frameRate: 60,
  videoBitrate: 100000000,
  minimumVideoBitrate: 100000000,
  maximumVideoBitrate: 100000000,
  rateControl: 'CBR'
});
